// Get the response directly
const response = $json; 
const toolCallId = $node["Main Switch"].json.body.message.toolCalls[0].id;

// Store services for future reference in the workflow
let allServices = [];

// Process the API response
let doctorsList = [];

// Check if we have a valid response
if (response) {
    // Extract doctors and services
    if (response.data && response.data.doctors && response.data.services) {
        const doctors = response.data.doctors;
        const services = response.data.services;

        // Store all services for later use
        allServices = services;

        doctorsList = doctors.map(doctor => {
            // Get services for this doctor
            const doctorServices = services.filter(service => 
                service.doctor_id === doctor.id.toString()
            );

            // Format doctor name and services
            const doctorName = doctor.first_name;
            const servicesList = doctorServices.map(s => {
                return `${s.title} ($${s.fee})`;
            }).join(', ');

            return `Dr. ${doctorName} (ID: ${doctor.id}) - Available Services: ${servicesList}`;
        });
    }
}

// If no doctors were processed, use default message
if (doctorsList.length === 0) {
    doctorsList = ['Currently no doctors available'];
}

const resultText = `Available doctors:\n${doctorsList.join('\n')}`;

// Save services info to be accessible in other nodes
const nodeContext = {
    services: allServices
};

return {
    results: [
        {
            toolCallId: toolCallId,
            result: resultText
        }
    ],
    services: allServices,  // Include services for other nodes to use
    nodeContext: nodeContext // Store in node context for workflow
};

