}

// Handle 'today' date conversion
let appointmentDateInput = parsedArgs.appointmentDate || '';
if (appointmentDateInput.toLowerCase() === 'today') {
  appointmentDateInput = new Date().toISOString().split('T')[0];
}

// Get services from previous node if available
let serviceId = parsedArgs.serviceId || 9; // Default service ID
const serviceName = parsedArgs.serviceName; // Get the service name from arguments

// Access previously stored services if available
let services = [];
try {
  // Try to get services from the Format Doctor List node
  const previousNodeData = $node["Format Doctor List"];
  if (previousNodeData && previousNodeData.json && previousNodeData.json.services) {
    services = previousNodeData.json.services;

    // If serviceName is provided, try to find matching service ID
    if (serviceName && services.length > 0) {
      const matchedService = services.find(service => 
        service.title.toLowerCase().includes(serviceName.toLowerCase())
      );

      if (matchedService) {
        serviceId = matchedService.id;
        console.log(`Found matching service ID ${serviceId} for service name: ${serviceName}`);
      }
    }
  }
} catch (error) {
  console.log('Error accessing services:', error.message);
}

return {
  toolCallId: $input.item.json.body.message.toolCalls[0]?.id || '',
  originalData: $input.item.json.body,
  doctorId: parsedArgs.doctorId, // Dynamic value from arguments
  appointmentDate: appointmentDateInput || new Date().toISOString().split('T')[0],
  hospitalOwnerId: parsedArgs.hospitalOwnerId || 1, // Static default value
  serviceId: serviceId, // Now using matched service ID if found
  serviceName: serviceName, // Store the service name for reference
  gms: parsedArgs.gms === true
};

