// Try multiple common slot locations
const slots = $json.slots || 
             $json.body?.slots || 
             $json.data?.slots || 
             $json.result?.slots || 
             [];

// Debug: Log raw slots data
console.log("DEBUG - Raw Slots Data:", JSON.stringify(slots, null, 2));

// Validate slots array
if (!Array.isArray(slots)) {
  console.log("DEBUG - Slots is not an array");
  return { 
    results: [{ 
      toolCallId, 
      result: "Invalid slots format received" 
    }] 
  };
}

// Handle empty slots case
if (slots.length === 0) {
  console.log("DEBUG - Empty slots array");
  return { 
    results: [{ 
      toolCallId, 
      result: "No available slots found for the selected date and doctor." 
    }] 
  };
}

// Initialize time categories
const timeCategories = {
  morning: { start: 0, end: 12, slots: [] },
  afternoon: { start: 12, end: 17, slots: [] },
  evening: { start: 17, end: 24, slots: [] }
};

// Categorize slots
slots.forEach(slot => {
  const startTime = slot.start_time || slot.startTime || slot.start;
  if (!startTime) return;

  const [hourStr] = startTime.split(':');
  const hour = parseInt(hourStr, 10);

  if (hour < timeCategories.morning.end) {
    timeCategories.morning.slots.push(slot);
  } else if (hour < timeCategories.afternoon.end) {
    timeCategories.afternoon.slots.push(slot);
  } else {
    timeCategories.evening.slots.push(slot);
  }
});

// Format slots with emojis
const formatCategory = (category, icon) => {
  if (category.slots.length === 0) return '';
  const formatted = category.slots.slice(0, 5).map(slot => {
    const start = slot.start_time || 'Unknown Start';
    const end = slot.end_time || 'Unknown End';
    return `⏰ ${start} - ${end}`;
  }).join('\n');
  return `${icon} ${category.slots.length} slots available:\n${formatted}\n\n`;
};

let resultText = '';
resultText += formatCategory(timeCategories.morning, '🌅 Morning');
resultText += formatCategory(timeCategories.afternoon, '☀️ Afternoon');
resultText += formatCategory(timeCategories.evening, '🌙 Evening');

// Handle no slots scenario
resultText = resultText.trim() || '❌ No available slots found for the selected date and doctor.';

// Add service info
